#!/usr/bin/env bash
# Marketing hotfix deploy — pricing/layout/plugins copy (paste on VPS as root).
#   bash /root/vps-marketing-hotfix-deploy.sh
set -euo pipefail
MARKETING="${1:-/var/www/nexlify}"
[ -d "$MARKETING" ] || { echo "ERROR: $MARKETING not found"; exit 1; }
echo "==> Extracting marketing hotfix files..."
TMP=$(mktemp -d)
trap 'rm -rf "$TMP"' EXIT
base64 -d << 'B64EOF' | tar xzf - -C "$TMP"

B64EOF
cp -f "$TMP/src/components/Features.tsx" "$MARKETING/src/components/"
cp -f "$TMP/src/components/PricingSection.tsx" "$MARKETING/src/components/"
cp -f "$TMP/src/components/PluginPricingSection.tsx" "$MARKETING/src/components/"
cp -f "$TMP/src/components/SocialProofSection.tsx" "$MARKETING/src/components/"
cp -f "$TMP/src/lib/plan-marketing.ts" "$MARKETING/src/lib/"
cp -f "$TMP/src/lib/help-faq.ts" "$MARKETING/src/lib/"
cp -f "$TMP/src/app/pricing/page.tsx" "$MARKETING/src/app/pricing/"
echo "==> Building..."
cd "$MARKETING"
rm -rf .next
npx prisma generate 2>&1 | tail -1
npm run build 2>&1 | tail -8
[ -f .next/BUILD_ID ] || { echo "ERROR: build failed"; exit 1; }
echo "==> Restarting PM2..."
pm2 restart nexlify-web --update-env 2>&1 | tail -3
pm2 save 2>/dev/null || true
sleep 2
echo "==> Verify"
curl -fsS http://127.0.0.1:13001/pricing 2>/dev/null | grep -oE 'Plugins included free|September 1, 2026|Free until' | head -5 || true
echo ""
echo "Done — hard-refresh https://nexlify.live/pricing"
